{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2185-11-03 20:14:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. I understand your dialysis line came loose today. Can you tell me what happened?"
    },
    {
      "turn_number": 2,
      "time": "2185-11-03 20:16:00",
      "speaker": "Patient",
      "text": "Yeah, it pulled out a bit at daycare. I was moving around and suddenly felt it shift. They couldn’t get any IV access, so they sent me here."
    },
    {
      "turn_number": 3,
      "time": "2185-11-03 20:18:00",
      "speaker": "Doctor",
      "text": "I see. You’ve had trouble with access before. We’ll need to fix the line. Interventional radiology will replace it under light sedation."
    },
    {
      "turn_number": 4,
      "time": "2185-11-03 20:20:00",
      "speaker": "Patient",
      "text": "Is that safe? Last time I had a line infection with MRSA."
    },
    {
      "turn_number": 5,
      "time": "2185-11-03 20:22:00",
      "speaker": "Doctor",
      "text": "We’re aware of your history. The team will use sterile technique, and we’ll monitor closely. No signs of infection now."
    },
    {
      "turn_number": 6,
      "time": "2185-11-03 21:30:00",
      "speaker": "Doctor",
      "text": "The procedure is done. They replaced your left subclavian dialysis line successfully. A midline was placed to help with sedation access."
    },
    {
      "turn_number": 7,
      "time": "2185-11-03 21:32:00",
      "speaker": "Patient",
      "text": "Good. Can I eat now? I’ve been NPO since yesterday."
    },
    {
      "turn_number": 8,
      "time": "2185-11-03 21:34:00",
      "speaker": "Doctor",
      "text": "Yes, you can start eating. We’ll get you something soon. You also had dialysis earlier and they removed about 3 liters of fluid."
    },
    {
      "turn_number": 9,
      "time": "2185-11-03 21:36:00",
      "speaker": "Patient",
      "text": "That makes sense. I’ve been feeling swollen in my legs."
    },
    {
      "turn_number": 10,
      "time": "2185-11-03 22:00:00",
      "speaker": "Doctor",
      "text": "We noticed some pitting edema. Your dry weight is 84.7 kg, and you were over that. Dialysis helped bring your blood pressure down."
    },
    {
      "turn_number": 11,
      "time": "2185-11-03 22:02:00",
      "speaker": "Patient",
      "text": "I’ve been trying, but sometimes I forget to check my weight."
    },
    {
      "turn_number": 12,
      "time": "2185-11-03 22:04:00",
      "speaker": "Doctor",
      "text": "It’s important to weigh yourself daily. Call your doctor if you gain more than 3 pounds in a day."
    },
    {
      "turn_number": 13,
      "time": "2185-11-04 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. We checked your labs last night. Your potassium was a bit high at 5.7, but dialysis corrected that."
    },
    {
      "turn_number": 14,
      "time": "2185-11-04 08:17:00",
      "speaker": "Patient",
      "text": "Should I change my diet?"
    },
    {
      "turn_number": 15,
      "time": "2185-11-04 08:19:00",
      "speaker": "Doctor",
      "text": "Keep avoiding high-potassium foods like bananas and oranges. Your other labs are stable."
    },
    {
      "turn_number": 16,
      "time": "2185-11-04 10:00:00",
      "speaker": "Doctor",
      "text": "Nursing also noted pressure ulcers on your left gluteal area. They’re not infected, but you’ll need wound care."
    },
    {
      "turn_number": 17,
      "time": "2185-11-04 10:02:00",
      "speaker": "Patient",
      "text": "I sit on my scooter a lot. Should I change how I sit?"
    },
    {
      "turn_number": 18,
      "time": "2185-11-04 10:04:00",
      "speaker": "Doctor",
      "text": "Yes, reposition every 30 minutes. Avoid putting all your weight on the left side. A home health nurse will help with wound care."
    },
    {
      "turn_number": 19,
      "time": "2185-11-04 14:30:00",
      "speaker": "Doctor",
      "text": "We’re clearing you to go home. Your line is working, and you’re stable after dialysis."
    },
    {
      "turn_number": 20,
      "time": "2185-11-04 14:32:00",
      "speaker": "Patient",
      "text": "Are my medications the same?"
    },
    {
      "turn_number": 21,
      "time": "2185-11-04 14:34:00",
      "speaker": "Doctor",
      "text": "Yes, no changes. Keep taking oxycodone for hip pain, gabapentin, Keppra, and all your other meds as before."
    },
    {
      "turn_number": 22,
      "time": "2185-11-04 14:36:00",
      "speaker": "Patient",
      "text": "And dialysis?"
    },
    {
      "turn_number": 23,
      "time": "2185-11-04 14:38:00",
      "speaker": "Doctor",
      "text": "Resume your regular schedule. The center will contact you. Make sure you’re home on time for visits."
    },
    {
      "turn_number": 24,
      "time": "2185-11-04 14:40:00",
      "speaker": "Patient",
      "text": "I’ll try. Sometimes I lose track."
    },
    {
      "turn_number": 25,
      "time": "2185-11-04 14:42:00",
      "speaker": "Doctor",
      "text": "They’re referring you to a new service to help with that. It’s important for your care."
    },
    {
      "turn_number": 26,
      "time": "2185-11-04 17:00:00",
      "speaker": "Doctor",
      "text": "Your midline was removed earlier. The dialysis line is secure and ready for use."
    },
    {
      "turn_number": 27,
      "time": "2185-11-04 17:02:00",
      "speaker": "Patient",
      "text": "Thanks. I feel better already."
    },
    {
      "turn_number": 28,
      "time": "2185-11-04 17:04:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and follow up with your doctors. We’ll see you if anything changes."
    }
  ],
  "summary": {
    "admission_start": "2185-11-03 20:14:00",
    "admission_end": "2185-11-04 19:03:00",
    "summary_paragraph": "The patient was admitted due to partial dislodgement of his left subclavian tunneled hemodialysis catheter, occurring during agitation at daycare. Given his history of difficult vascular access and prior MRSA line infections, interventional radiology successfully replaced the dialysis line under MAC anesthesia, using a left midline catheter for procedural access. The new line was placed without complications and confirmed functional. He underwent dialysis with removal of 3 liters of fluid, improving volume overload. Pressure ulcers were noted at the left gluteal fold, and the patient was counseled on repositioning and wound care. All home medications were continued without change. He was discharged home with services, advised to resume regular dialysis, monitor daily weight, and follow up with outpatient support for visit compliance.",
    "problems": [
      "End stage renal disease",
      "Other complications due to renal dialysis device, implant, and graft",
      "Pressure ulcer, unstageable",
      "Chronic systolic heart failure",
      "Pain in joint, pelvic region and thigh",
      "Seizure disorder",
      "Anemia in chronic kidney disease",
      "Gout",
      "Esophageal reflux",
      "Coronary atherosclerosis",
      "Old myocardial infarction",
      "Personal history of transient ischemic attack (TIA), and cerebral infarction without residual deficits"
    ]
  }
}
